algorithms.pseudocode:
function FIB_ENTRY(p, limit):
    if p <= 0: return 0
    if p == 1: return 1
    (a, b) <- (0, 1)            # a = F(0) mod p, b = F(1) mod p
    for k from 1 to limit:
        (a, b) <- (b, (a + b) mod p)   # advance: a becomes F(k) mod p
        if a == 0: return k     # first positive index with p | F(k)
    return 0                    # no entry point within the bound

