function LEAST_PRIMITIVE_PRIME_DIVISOR(n):
    f <- F(n)
    if f <= 1: return NONE          # n in {1, 2}: F(n) is a unit
    for p in ascending prime factors of f:
        if is_prime(p) and (F(n) mod p == 0) and FIB_ENTRY(p) == n:
            return p                # z(p) = n  <=>  primitive
    return NONE                     # n in {6, 12}: no primitive divisor

